const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');const hoverPointer=window.matchMedia('(hover: hover) and (pointer: fine)');const dialog=document.querySelector('.certificate-dialog');const preview=dialog.querySelector('img');const close=dialog.querySelector('.certificate-close');
document.querySelectorAll('.credential-badge').forEach(button=>{button.addEventListener('click',()=>{const source=button.querySelector('img');preview.src=source.src;preview.alt=source.alt;dialog.showModal()});const reset=()=>{button.classList.remove('is-hovering');button.style.removeProperty('--badge-rotate-x');button.style.removeProperty('--badge-rotate-y')};button.addEventListener('pointermove',event=>{if(event.pointerType==='touch'||reducedMotion.matches||!hoverPointer.matches)return;const bounds=button.getBoundingClientRect();const x=Math.max(-1,Math.min(1,(event.clientX-bounds.left)/bounds.width*2-1));const y=Math.max(-1,Math.min(1,(event.clientY-bounds.top)/bounds.height*2-1));button.classList.add('is-hovering');button.style.setProperty('--badge-rotate-x',`${-y*25}deg`);button.style.setProperty('--badge-rotate-y',`${x*32}deg`)});button.addEventListener('pointerleave',reset);button.addEventListener('pointercancel',reset);reducedMotion.addEventListener('change',reset);hoverPointer.addEventListener('change',reset)});close.addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});window.addEventListener('blur',()=>document.querySelectorAll('.credential-badge').forEach(button=>{button.classList.remove('is-hovering');button.style.removeProperty('--badge-rotate-x');button.style.removeProperty('--badge-rotate-y')}));